.subckt SUB_1 Vbiasn Vbiasp VDD GND
  xmsu2 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xmsu2} l={L_xmsu2}
  xmsu1 N001 Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xmsu1} l={L_xmsu1}
  xmsu3 VDD N001 Vbiasn 0 sky130_fd_pr__nfet_01v8 w={W_xmsu3} l={L_xmsu3}
  xm3 Vbiasn Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3} l={L_xm3}
  xm4 Vbiasp Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
  xm1 Vbiasn Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
  xm2 Vbiasp Vbiasn N002 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  R1 N002 GND 6.5k
.ends SUB_1

* Sources: Vm held at mid-rail (0.9V)
Vm vm 0 0.9
* Vp with DC value and pulse for transient overdrive
Vp vp 0 dc 0.9 pulse(0.85 0.95 20n 100p 100p 10n 40n)

* Load capacitor
Cload Out 0 20f

.control
* 1. Operating Point Analysis
op
let idd_q = -i(VDD)
let p_diss = idd_q * 1.8
print idd_q p_diss

* 2. DC Transfer Curve and Gain
dc Vp 0.88 0.92 0.05m
let v_out = v(Out)
let deriv_gain = deriv(v(Out))
let max_gain = vecmax(deriv_gain)
let gain_db = 20 * log(max_gain)
meas dc v_switch when v(Out)=0.9 rise=1
let v_offset = v_switch - 0.9
meas dc voh max v(Out)
meas dc vol min v(Out)
print max_gain gain_db v_switch v_offset voh vol

* 3. Transient Response (50 mV Overdrive)
tran 0.05n 50n
meas tran t_cross_in  when v(vp)=0.9 rise=1
meas tran t_cross_out when v(Out)=0.9 rise=1
let t_prop_delay = t_cross_out - t_cross_in
print t_prop_delay

quit
.endc
.end

